const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.goto('file:///app/output/hunger-crisis-poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Get infographic background color
  const impactBg = await page.evaluate(() => {
    const svg = document.querySelector('#impact-infographic svg');
    const style = svg ? window.getComputedStyle(svg) : null;
    const firstRect = document.querySelector('#impact-infographic svg rect');
    return {
      svgBg: style?.backgroundColor,
      firstRectFill: firstRect?.getAttribute('fill'),
      svgWidth: svg?.getAttribute('width'),
      svgHeight: svg?.getAttribute('height'),
      viewBox: svg?.getAttribute('viewBox')
    };
  });
  console.log('Impact SVG info:', JSON.stringify(impactBg, null, 2));

  // Check overall poster layout
  const layoutInfo = await page.evaluate(() => {
    const poster = document.querySelector('.poster');
    const sections = poster?.children;
    const info = [];
    for (let i = 0; i < sections.length; i++) {
      const rect = sections[i].getBoundingClientRect();
      info.push({ class: sections[i].className, top: Math.round(rect.top), height: Math.round(rect.height) });
    }
    return info;
  });
