<html>
<head>
  <meta charset="utf-8">
  <title>Hunger Doesn't Wait - Advocacy Poster</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800;900&display=swap');

    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      width: 1200px;
      height: 1800px;
      background: #0d1117;
      font-family: 'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
      color: #ffffff;
      overflow: hidden;
      -webkit-font-smoothing: antialiased;
    }

    .poster {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      position: relative;
    }

    /* Subtle background texture */
    .poster::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background:
        radial-gradient(ellipse 800px 600px at 20% 10%, rgba(232, 97, 45, 0.08) 0%, transparent 70%),
        radial-gradient(ellipse 600px 400px at 80% 85%, rgba(245, 166, 35, 0.06) 0%, transparent 70%);
      pointer-events: none;
      z-index: 0;
    }

    .poster > * {
      position: relative;
      z-index: 1;
    }

    /* ==================== TITLE SECTION ==================== */
    .title-section {
      padding: 55px 70px 10px;
    }

    .title-section h1 {
      font-size: 58px;
      font-weight: 900;
      line-height: 1.08;
      letter-spacing: -1.5px;
      color: #ffffff;
    }

    .title-section h1 .accent {
      color: #e8612d;
    }

    .title-section .subtitle {
      font-size: 30px;
      color: #f5a623;
      margin-top: 8px;
      font-weight: 400;
      letter-spacing: 0.5px;
    }

    .accent-line {
      width: 100px;
      height: 4px;
      background: linear-gradient(90deg, #e8612d, #f5a623);
      margin-top: 18px;
      border-radius: 2px;
    }

    /* ==================== CRISIS SECTION ==================== */
    .crisis-section {
      padding: 25px 70px 15px;
      display: flex;
      gap: 40px;
      align-items: flex-start;
    }

    .crisis-stat {
      flex: 1;
    }

    .crisis-stat .number {
      font-size: 88px;
      font-weight: 900;
      line-height: 1;
      letter-spacing: -3px;
    }

    .crisis-stat .number.primary {
      color: #e8612d;
      text-shadow: 0 0 60px rgba(232, 97, 45, 0.25);
    }

    .crisis-stat .number.secondary {
      font-size: 72px;
      color: #f5a623;
      text-shadow: 0 0 50px rgba(245, 166, 35, 0.2);
    }

    .crisis-stat .label {
      font-size: 22px;
      color: #e8e0d4;
      margin-top: 6px;
      font-weight: 600;
    }

    .crisis-stat .context {
      font-size: 15px;
      color: #8b949e;
      margin-top: 3px;
      line-height: 1.4;
    }

    .crisis-divider {
      width: 1px;
      height: 90px;
      background: linear-gradient(180deg, rgba(232, 97, 45, 0.4), rgba(245, 166, 35, 0.1));
      margin-top: 10px;
      align-self: flex-start;
    }

    /* ==================== IMPACT SECTION ==================== */
    .impact-section {
      padding: 15px 70px 10px;
    }

    .section-heading {
      font-size: 20px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 3px;
      color: #8b949e;
      margin-bottom: 18px;
    }

    .section-heading::after {
      content: '';
      display: inline-block;
      width: 40px;
      height: 2px;
      background: #e8612d;
      margin-left: 12px;
      vertical-align: middle;
    }

    #impact-infographic {
      width: 1060px;
      height: 340px;
    }

    /* ==================== CONVERSION SECTION ==================== */
    .conversion-section {
      padding: 20px 70px;
    }

    .conversion-box {
      background: linear-gradient(135deg, rgba(232, 97, 45, 0.12) 0%, rgba(245, 166, 35, 0.08) 100%);
      border: 2px solid rgba(232, 97, 45, 0.35);
      border-radius: 16px;
      padding: 28px 40px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .conversion-box::before {
      content: '';
      position: absolute;
      top: -50%;
      left: -50%;
      width: 200%;
      height: 200%;
      background: radial-gradient(circle at center, rgba(232, 97, 45, 0.05) 0%, transparent 50%);
      pointer-events: none;
    }

    .conversion-amount {
      font-size: 68px;
      font-weight: 900;
      letter-spacing: -2px;
      background: linear-gradient(135deg, #e8612d, #f5a623);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .conversion-desc {
      font-size: 19px;
      color: #e8e0d4;
      margin-top: 6px;
      font-weight: 400;
    }

    .conversion-note {
      font-size: 15px;
      color: #f5a623;
      margin-top: 5px;
      font-weight: 600;
    }

    /* ==================== ACTION SECTION ==================== */
    .action-section {
      padding: 15px 70px 10px;
    }

    #action-infographic {
      width: 1060px;
      height: 340px;
    }

    /* ==================== FOUR PILLARS ==================== */
    .pillars-section {
      padding: 10px 70px;
    }

    .pillars-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }

    .pillar-card {
      background: rgba(22, 27, 34, 0.6);
      border: 1px solid rgba(232, 97, 45, 0.12);
      border-radius: 10px;
      padding: 16px 18px;
    }

    .pillar-card .pillar-label {
      font-size: 15px;
      font-weight: 700;
      color: #f5a623;
      margin-bottom: 4px;
    }

    .pillar-card .pillar-desc {
      font-size: 13px;
      color: #8b949e;
      line-height: 1.4;
    }

    /* ==================== FOOTER ==================== */
    .footer {
      padding: 20px 70px 40px;
      text-align: center;
      margin-top: auto;
    }

    .footer-quote {
      font-size: 18px;
      color: #e8e0d4;
      font-style: italic;
      line-height: 1.5;
      max-width: 800px;
      margin: 0 auto;
    }

    .footer-org {
      font-size: 14px;
      color: #8b949e;
      margin-top: 10px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 2px;
    }
  </style>
</head>
<body>
  <div class="poster">
    <!-- Title Section -->
    <div class="title-section">
      <h1>HUNGER DOESN'T WAIT<span class="accent"> —</span><br>Together We Can End It</h1>
      <div class="accent-line"></div>
    </div>

    <!-- Crisis Stats -->
    <div class="crisis-section">
      <div class="crisis-stat">
        <div class="number primary">48M</div>
        <div class="label">Americans face hunger</div>
        <div class="context">across all 50 states and Puerto Rico</div>
      </div>
      <div class="crisis-divider"></div>
      <div class="crisis-stat">
        <div class="number secondary">14M</div>
        <div class="label">Children affected</div>
        <div class="context">families struggle to put food on the table</div>
      </div>
    </div>

    <!-- Impact Section -->
    <div class="impact-section">
      <div class="section-heading">Our Collective Impact</div>
      <div id="impact-infographic"></div>
    </div>

    <!-- Conversion Highlight -->
    <div class="conversion-section">
      <div class="conversion-box">
        <div class="conversion-amount">$1 = 10 MEALS</div>
        <div class="conversion-desc">Every dollar provides at least 10 meals to neighbors in need</div>
        <div class="conversion-note">Gifts matched for a limited time — move fresh food to neighbors fast</div>
      </div>
    </div>

    <!-- Action Section -->
    <div class="action-section">
      <div class="section-heading">How You Can Make a Difference</div>
      <div id="action-infographic"></div>
    </div>

    <!-- Footer -->
    <div class="footer">
      <div class="footer-quote">"Hunger touches every community, but together, we can meet this moment. An America without hunger is within reach."</div>
      <div class="footer-org">Feeding America</div>
    </div>
  </div>

  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const impactSyntax = `infographic list-grid-badge-card
data
  title
  lists
    - label Meals Distributed
      value 5.7
      desc Billion meals provided through the network
      icon restaurant
    - label Food Rescued
      value 4.3
      desc Billion pounds saved from waste
      icon recycle
    - label Free Food Programs
      value 60000
      desc Programs distributing free food
      icon building
    - label Food Banks
      value 200
      desc Food banks across the nation
      icon location
theme
  palette #e8612d #f5a623 #c94420 #d4a03c`;

    const actionSyntax = `infographic list-grid-badge-card
data
  title
  lists
    - label Donate
      desc Every $1 provides 10 meals to neighbors in need
      icon heart
    - label Advocate
      desc Urge lawmakers to support hunger relief programs
      icon megaphone
    - label Fundraise
      desc Inspire your community to come together and act
      icon people
    - label Volunteer
      desc Help sort, pack and distribute food where needed
      icon hands
theme
  palette #e8612d #f5a623 #c94420 #d4a03c`;

    const impactInfographic = new AntVInfographic.Infographic({
      container: '#impact-infographic',
      width: 1060,
      height: 340,
    });
    impactInfographic.render(impactSyntax);

    const actionInfographic = new AntVInfographic.Infographic({
      container: '#action-infographic',
      width: 1060,
      height: 340,
    });
    actionInfographic.render(actionSyntax);

    document.fonts?.ready.then(() => {
      impactInfographic.render(impactSyntax);
      actionInfographic.render(actionSyntax);
    }).catch((error) => console.error('Error waiting for fonts to load:', error));
  </script>
</body>
</html>
", "userModified": false}

