(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.goto('file:///app/output/hunger-crisis-poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  const layoutInfo = await page.evaluate(() => {
    const poster = document.querySelector('.poster');
    const sections = poster?.children;
    const info = [];
    for (let i = 0; i < sections.length; i++) {
      const rect = sections[i].getBoundingClientRect();
      info.push({ class: sections[i].className, top: Math.round(rect.top), height: Math.round(rect.height) });
    }
    return info;
  });
  console.log('Layout info:', JSON.stringify(layoutInfo, null, 2));

  // Check total used space
  const lastSection = layoutInfo[layoutInfo.length - 1];
  const totalUsed = lastSection.top + lastSection.height;
  console.log('Total used space:', totalUsed, 'of 1800px');
  console.log('Remaining space:', 1800 - totalUsed);

  await browser.close();
})();
