const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.goto('file:///app/output/hunger-crisis-poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(4000);

  // Get the full SVG HTML to understand rendering
  const svgInfo = await page.evaluate(() => {
    const container = document.querySelector('#impact-infographic');
    const svg = container?.querySelector('svg');
    if (!svg) return 'No SVG found';

    // Check for foreignObject (HTML content in SVG)
    const foreignObjects = svg.querySelectorAll('foreignObject');
    const allElements = svg.querySelectorAll('*');

    // Get text from all possible sources
    const textContent = [];
    svg.querySelectorAll('text, tspan, foreignObject div, foreignObject span, foreignObject p').forEach(el => {
      const t = el.textContent?.trim();
      if (t && t.length > 0 && t.length < 100) textContent.push(t);
    });

    return {
      svgTagCount: allElements.length,
      foreignObjectCount: foreignObjects.length,
      textContent: textContent.slice(0, 20),
      svgInnerHTMLLength: svg.innerHTML.length,
      firstChars: svg.innerHTML.substring(0, 500)
    };
  });
  console.log('SVG info:', JSON.stringify(svgInfo, null, 2));

  await browser.close();
})();
" 2>&1

