const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.goto('file:///app/output/hunger-crisis-poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(4000);

  const layoutInfo = await page.evaluate(() => {
    const poster = document.querySelector('.poster');
    const sections = poster?.children;
    const info = [];
    for (let i = 0; i < sections.length; i++) {
      const rect = sections[i].getBoundingClientRect();
      info.push({ class: sections[i].className, top: Math.round(rect.top), bottom: Math.round(rect.top + rect.height), height: Math.round(rect.height) });
    }
    return info;
  });
  console.log('Layout info:');
  layoutInfo.forEach(s => console.log('  ' + s.class + ': ' + s.top + '-' + s.bottom + ' (' + s.height + 'px)'));

  const last = layoutInfo[layoutInfo.length - 1];
  console.log('Total used:', last.bottom, 'of 1800px');

  // Verify infographic content rendered
  const texts = await page.evaluate(() => {
    const svg1 = document.querySelector('#impact-infographic svg');
    const svg2 = document.querySelector('#action-infographic svg');
    const t1 = Array.from(svg1?.querySelectorAll('text, tspan, foreignObject div, foreignObject span') || []).map(e => e.textContent?.trim()).filter(Boolean);
    const t2 = Array.from(svg2?.querySelectorAll('text, tspan, foreignObject div, foreignObject span') || []).map(e => e.textContent?.trim()).filter(Boolean);
    return { impact: t1.slice(0, 12), action: t2.slice(0, 12) };
  });
  console.log('Impact content:', texts.impact);
  console.log('Action content:', texts.action);

  await browser.close();
})();
" 2>&1

