const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Set viewport to poster size, with 2x device scale for high-quality output
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.emulateMedia({ colorScheme: 'dark' });

  const htmlPath = path.resolve('/app/output/hunger-crisis-poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for fonts and infographics to fully render
  await page.waitForTimeout(4000);

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: false,
    type: 'png',
    scale: 'css',
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();

