node -e "
const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ deviceScaleFactor: 2 });
  const page = await context.newPage();
  await page.setViewportSize({ width: 1200, height: 1800 });
  await page.goto('file:///app/output/hunger-crisis-poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(4000);

  // Final verification
  const check = await page.evaluate(() => {
    const results = {};

    // Check title
    const h1 = document.querySelector('.title-section h1');
    results.title = h1?.textContent?.trim();

    // Check crisis numbers
    const numbers = document.querySelectorAll('.crisis-stat .number');
    results.crisisNumbers = Array.from(numbers).map(n => n.textContent?.trim());

    // Check infographic content
    const impactSvg = document.querySelector('#impact-infographic svg');
    const actionSvg = document.querySelector('#action-infographic svg');
    results.impactRendered = !!impactSvg;
    results.actionRendered = !!actionSvg;

    // Check conversion
    const conversion = document.querySelector('.conversion-amount');
    results.conversion = conversion?.textContent?.trim();

    // Check pillars
    const pillarLabels = document.querySelectorAll('.pillar-label');
    results.pillars = Array.from(pillarLabels).map(p => p.textContent?.trim());

    // Check footer
    const footer = document.querySelector('.footer-quote');
    results.footer = footer?.textContent?.trim()?.substring(0, 80);

    return results;
  });
  console.log('Final verification:', JSON.stringify(check, null, 2));

  await browser.close();
})();
" 2>&1

